SELECT CAST(j.did AS VARCHAR) AS user_id, make_timestamp(CAST(MIN(CAST(j.time_us AS BIGINT)) / 1000000 AS BIGINT)) AS first_post_date FROM bluesky WHERE CAST(j.kind AS VARCHAR) = 'commit' AND CAST(j.commit.operation AS VARCHAR) = 'create' AND CAST(j.commit.collection AS VARCHAR) = 'app.bsky.feed.post' GROUP BY user_id ORDER BY first_post_date ASC, user_id LIMIT 3;
